1	package com.example.starter.observation;
2	
3	import com.fasterxml.jackson.core.JsonProcessingException;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.springframework.dao.DuplicateKeyException;
6	import org.springframework.http.HttpStatus;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	import java.math.BigDecimal;
11	import java.nio.charset.StandardCharsets;
12	import java.security.MessageDigest;
13	import java.security.NoSuchAlgorithmException;
14	import java.util.ArrayList;
15	import java.util.HexFormat;
16	import java.util.List;
17	import java.util.Objects;
18	import java.util.Optional;
19	
20	/**
21	 * 现场观测离线三方合并业务服务。
22	 *
23	 * <p>写操作（创建/离线提交/删除）均在单事务内完成：先占位写入幂等去重记录，
24	 * 再对 observation_current 行加锁（SELECT ... FOR UPDATE）完成业务判定与变更，
25	 * 最后回填去重记录的响应并整体提交；任何业务失败都会回滚，去重记录不占键。
26	 *
27	 * <p>合并规则（按字段比较基线 base、当前 current、候选 candidate）：
28	 * 候选未改（等于基线）保留当前；当前未改接受候选；两边改为相同值也接受；
29	 * 否则整次 409，不写入任何部分结果。读数按数值比较，其余字段按原文比较。
30	 */
31	@Service
32	public class ObservationService {
33	
34	    private static final String SEPARATOR = "\u0001";
35	
36	    private final ObservationRepository observationRepository;
37	    private final RequestLogRepository requestLogRepository;
38	    private final ObjectMapper objectMapper;
39	
40	    public ObservationService(ObservationRepository observationRepository,
41	                              RequestLogRepository requestLogRepository,
42	                              ObjectMapper objectMapper) {
43	        this.observationRepository = observationRepository;
44	        this.requestLogRepository = requestLogRepository;
45	        this.objectMapper = objectMapper;
46	    }
47	
48	    /**
49	     * 创建观测记录，初始版本为 1。记录已存在返回 409。
50	     */
51	    @Transactional
52	    public WriteOutcome create(CreateObservationRequest request) {
53	        String fingerprint = fingerprint("CREATE", request.observationId(), request.location(),
54	                request.reading(), request.note());
55	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
56	        if (replayed != null) {
57	            return replayed;
58	        }
59	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "CREATE");
60	        if (concurrent != null) {
61	            return concurrent;
62	        }
63	
64	        if (observationRepository.findCurrentForUpdate(request.observationId()).isPresent()) {
65	            throw ApiException.conflict("observation already exists: " + request.observationId(), null);
66	        }
67	        ObservationSnapshot snapshot = new ObservationSnapshot(request.observationId(), 1,
68	                request.location(), request.reading(), request.note(), false);
69	        try {
70	            observationRepository.insertCurrent(snapshot);
71	        } catch (DuplicateKeyException e) {
72	            // 并发创建同一 observationId：由主键串行化，后到者按冲突处理
73	            throw ApiException.conflict("observation already exists: " + request.observationId(), null);
74	        }
75	        observationRepository.insertVersion(snapshot);
76	        return complete(request.requestId(), HttpStatus.CREATED, ObservationResponse.of(snapshot));
77	    }
78	
79	    /**
80	     * 离线提交：基于 baseVersion 的三方合并。合并结果与当前完全相同则不加版本，否则版本加一。
81	     */
82	    @Transactional
83	    public WriteOutcome merge(String observationId, MergeObservationRequest request) {
84	        String fingerprint = fingerprint("MERGE", observationId, String.valueOf(request.baseVersion()),
85	                request.location(), request.reading(), request.note());
86	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
87	        if (replayed != null) {
88	            return replayed;
89	        }
90	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "MERGE");
91	        if (concurrent != null) {
92	            return concurrent;
93	        }
94	
95	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
96	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
97	        if (current.deleted()) {
98	            throw ApiException.gone("observation already deleted: " + observationId);
99	        }
100	        ObservationSnapshot base = observationRepository.findVersion(observationId, request.baseVersion())
101	                .orElseThrow(() -> ApiException.notFound(
102	                        "base version not found: " + observationId + "@" + request.baseVersion()));
103	
104	        List<String> conflictFields = new ArrayList<>();
105	        String mergedLocation = mergeField("location", base.location(), current.location(),
106	                request.location(), conflictFields);
107	        String mergedReading = mergeReadingField(base.reading(), current.reading(),
108	                request.reading(), conflictFields);
109	        String mergedNote = mergeField("note", base.note(), current.note(), request.note(), conflictFields);
110	        if (!conflictFields.isEmpty()) {
111	            throw ApiException.mergeConflict(conflictFields, current.version());
112	        }
113	
114	        ObservationSnapshot merged = new ObservationSnapshot(observationId, current.version(),
115	                mergedLocation, mergedReading, mergedNote, false);
116	        if (sameContent(merged, current)) {
117	            // 合并结果与当前完全相同：返回当前版本，不加版本
118	            return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(current));
119	        }
120	        ObservationSnapshot next = new ObservationSnapshot(observationId, current.version() + 1,
121	                mergedLocation, mergedReading, mergedNote, false);
122	        observationRepository.updateCurrent(next);
123	        observationRepository.insertVersion(next);
124	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(next));
125	    }
126	
127	    /**
128	     * 删除观测记录：expectedVersion 匹配当前版本时生成新版本墓碑；已删除记录返回 410。
129	     */
130	    @Transactional
131	    public WriteOutcome delete(String observationId, DeleteObservationRequest request) {
132	        String fingerprint = fingerprint("DELETE", observationId, String.valueOf(request.expectedVersion()));
133	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
134	        if (replayed != null) {
135	            return replayed;
136	        }
137	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "DELETE");
138	        if (concurrent != null) {
139	            return concurrent;
140	        }
141	
142	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
143	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
144	        if (current.deleted()) {
145	            throw ApiException.gone("observation already deleted: " + observationId);
146	        }
147	        if (request.expectedVersion() != current.version()) {
148	            throw ApiException.conflict("expectedVersion mismatch", current.version());
149	        }
150	        ObservationSnapshot tombstone = new ObservationSnapshot(observationId, current.version() + 1,
151	                null, null, null, true);
152	        observationRepository.markDeleted(observationId, tombstone.version());
153	        observationRepository.insertVersion(tombstone);
154	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(tombstone));
155	    }
156	
157	    /**
158	     * 查询当前内容；墓碑只返回删除状态和版本。
159	     */
160	    @Transactional(readOnly = true)
161	    public ObservationResponse getCurrent(String observationId) {
162	        ObservationSnapshot current = observationRepository.findCurrent(observationId)
163	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
164	        return ObservationResponse.of(current);
165	    }
166	
167	    /**
168	     * 查询指定历史版本；墓碑版本只返回删除状态和版本。
169	     */
170	    @Transactional(readOnly = true)
171	    public ObservationResponse getVersion(String observationId, int version) {
172	        ObservationSnapshot snapshot = observationRepository.findVersion(observationId, version)
173	                .orElseThrow(() -> ApiException.notFound(
174	                        "version not found: " + observationId + "@" + version));
175	        return ObservationResponse.of(snapshot);
176	    }
177	
178	    /**
179	     * 普通字段三方合并：候选未改保留当前；当前未改接受候选；两边改为相同值接受；否则记录冲突。
180	     */
181	    private String mergeField(String field, String base, String current, String candidate,
182	                              List<String> conflictFields) {
183	        if (Objects.equals(candidate, base)) {
184	            return current;
185	        }
186	        if (Objects.equals(current, base) || Objects.equals(candidate, current)) {
187	            return candidate;
188	        }
189	        conflictFields.add(field);
190	        return current;
191	    }
192	
193	    /**
194	     * 读数字段三方合并：按数值比较（BigDecimal），其余规则与普通字段一致。
195	     */
196	    private String mergeReadingField(String base, String current, String candidate,
197	                                     List<String> conflictFields) {
198	        if (readingEquals(candidate, base)) {
199	            return current;
200	        }
201	        if (readingEquals(current, base) || readingEquals(candidate, current)) {
202	            return candidate;
203	        }
204	        conflictFields.add("reading");
205	        return current;
206	    }
207	
208	    /**
209	     * 判断合并结果与当前版本内容是否完全相同（读数按数值，其余按原文）。
210	     */
211	    private boolean sameContent(ObservationSnapshot merged, ObservationSnapshot current) {
212	        return Objects.equals(merged.location(), current.location())
213	                && Objects.equals(merged.note(), current.note())
214	                && readingEquals(merged.reading(), current.reading());
215	    }
216	
217	    private boolean readingEquals(String left, String right) {
218	        if (left == null || right == null) {
219	            return Objects.equals(left, right);
220	        }
221	        return new BigDecimal(left).compareTo(new BigDecimal(right)) == 0;
222	    }
223	
224	    /**
225	     * 幂等检查：同键同参返回原成功结果；同键异参返回 409；无记录返回 null 继续执行。
226	     */
227	    private WriteOutcome checkReplay(String requestId, String fingerprint) {
228	        Optional<RequestLogEntry> existing = requestLogRepository.find(requestId);
229	        if (existing.isEmpty()) {
230	            return null;
231	        }
232	        RequestLogEntry entry = existing.get();
233	        if (!entry.fingerprint().equals(fingerprint)) {
234	            throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
235	        }
236	        return new WriteOutcome(entry.responseStatus(), readBody(entry.responseBody()));
237	    }
238	
239	    /**
240	     * 占位写入去重记录；并发同键时主键冲突，等待对方事务结束后读取已提交结果：
241	     * 同参返回重放结果，异参抛 409；正常占位返回 null。业务失败时占位随事务回滚，不占键。
242	     */
243	    private WriteOutcome insertPlaceholder(String requestId, String fingerprint, String operation) {
244	        try {
245	            requestLogRepository.insertPlaceholder(requestId, fingerprint, operation);
246	            return null;
247	        } catch (DuplicateKeyException e) {
248	            RequestLogEntry entry = requestLogRepository.find(requestId)
249	                    .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
250	            if (!entry.fingerprint().equals(fingerprint)) {
251	                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
252	            }
253	            return new WriteOutcome(entry.responseStatus(), readBody(entry.responseBody()));
254	        }
255	    }
256	
257	    /**
258	     * 业务成功后回填去重记录响应，并构造本次写操作结果；与业务变更同事务提交。
259	     */
260	    private WriteOutcome complete(String requestId, HttpStatus status, ObservationResponse body) {
261	        requestLogRepository.complete(requestId, status.value(), writeBody(body));
262	        return new WriteOutcome(status.value(), body);
263	    }
264	
265	    private String fingerprint(String operation, String... parts) {
266	        StringBuilder raw = new StringBuilder(operation);
267	        for (String part : parts) {
268	            raw.append(SEPARATOR).append(part == null ? "<null>" : part);
269	        }
270	        try {
271	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
272	            return HexFormat.of().formatHex(digest.digest(raw.toString().getBytes(StandardCharsets.UTF_8)));
273	        } catch (NoSuchAlgorithmException e) {
274	            throw new IllegalStateException("SHA-256 not available", e);
275	        }
276	    }
277	
278	    private String writeBody(ObservationResponse body) {
279	        try {
280	            return objectMapper.writeValueAsString(body);
281	        } catch (JsonProcessingException e) {
282	            throw new IllegalStateException("failed to serialize response", e);
283	        }
284	    }
285	
286	    private ObservationResponse readBody(String json) {
287	        try {
288	            return objectMapper.readValue(json, ObservationResponse.class);
289	        } catch (JsonProcessingException e) {
290	            throw new IllegalStateException("failed to deserialize stored response", e);
291	        }
292	    }
293	
294	    /**
295	     * 写操作结果：HTTP 状态码与响应体。
296	     */
297	    public record WriteOutcome(int status, ObservationResponse body) {
298	    }
299	}
