18	public record MergeObservationRequest(
19	        @NotBlank @Size(max = 128) String requestId,
20	        @NotNull @Min(1) Integer baseVersion,
21	        @NotNull @Size(max = 512) String location,
22	        @NotNull @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
23	        String reading,
24	        @NotNull @Size(max = 1024) String note) {
