@Transactional
public WriteOutcome<ResolutionResponse> resolve(String observationId, ResolveObservationRequest request) {
    String selectionsCanonical = canonicalSelections(request.selections()); // sorted "k=v" joined
    String fingerprint = fingerprint("RESOLVE", observationId, request.resolutionId(),
            String.valueOf(request.baseVersion()), String.valueOf(request.expectedCurrentVersion()),
            request.location(), request.reading(), request.note(), selectionsCanonical, request.operator());
    WriteOutcome<ResolutionResponse> replayed = checkReplay(request.requestId(), fingerprint, ResolutionResponse.class);
    if (replayed != null) return replayed;
    WriteOutcome<ResolutionResponse> concurrent = insertPlaceholder(request.requestId(), fingerprint, "RESOLVE", ResolutionResponse.class);
    if (concurrent != null) return concurrent;

    ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
            .orElseThrow(() -> ApiException.notFound(...));
    if (current.deleted()) throw ApiException.gone(...);

    // resolutionId 全局唯一：同参重放返回原结果，异参 409
    String resolutionFingerprint = fingerprint("RESOLUTION", observationId,
            String.valueOf(request.baseVersion()), String.valueOf(request.expectedCurrentVersion()),
            request.location(), request.reading(), request.note(), selectionsCanonical, request.operator());
